namespace EnumClass.Generator
{
    /// <summary>Source added to every consuming compilation once (post-initialization).</summary>
    internal static class RuntimeSources
    {
        public const string Attributes = """
            // <auto-generated/>
            #nullable enable
            namespace EnumClass
            {
                /// <summary>
                /// Marks a <c>readonly partial struct</c> as a data enum. Declare data as
                /// <c>public partial T Prop { get; }</c> and members as
                /// <c>[Member(...)] public static partial Self Name { get; }</c>.
                /// </summary>
                [global::System.AttributeUsage(global::System.AttributeTargets.Struct, Inherited = false)]
                [global::System.Diagnostics.Conditional("EnumClass_KEEP_ATTRIBUTES")]
                internal sealed class EnumClassAttribute : global::System.Attribute { }

                /// <summary>
                /// Declares a member. Values bind positionally to the instance partial
                /// properties, in declaration order. Values must be attribute constants
                /// (primitives, string, enum, typeof, 1-D arrays thereof, null).
                /// </summary>
                [global::System.AttributeUsage(global::System.AttributeTargets.Property, Inherited = false)]
                [global::System.Diagnostics.Conditional("EnumClass_KEEP_ATTRIBUTES")]
                internal sealed class MemberAttribute : global::System.Attribute
                {
                    public MemberAttribute(params object?[] values) => Values = values;
                    public object?[] Values { get; }
                }
            }
            """;

        // Must stay bit-identical to PerfectHashBuilder.Hash / Reduce.
        public const string PerfectHash = """
            // <auto-generated/>
            #nullable enable
            namespace EnumClass.Internal
            {
                internal static class PerfectHash
                {
                    [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
                    public static uint Hash(global::System.ReadOnlySpan<char> key, uint seed, bool fold)
                    {
                        unchecked
                        {
                            uint h = 2166136261u ^ (seed * 0x9E3779B9u);
                            foreach (char ch in key)
                            {
                                uint c = ch;
                                if (fold && c - 'A' <= 25u) c |= 0x20u;
                                h = (h ^ c) * 16777619u;
                            }
                            h ^= h >> 16; h *= 0x85EBCA6Bu;
                            h ^= h >> 13; h *= 0xC2B2AE35u;
                            h ^= h >> 16;
                            return h;
                        }
                    }

                    [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
                    public static int Reduce(uint h, int n) => (int)(((ulong)h * (uint)n) >> 32);

                    /// <summary>Returns the candidate slot; the caller must still compare the key.</summary>
                    [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
                    public static int Slot(global::System.ReadOnlySpan<char> key, global::System.ReadOnlySpan<int> displacements, bool fold)
                    {
                        int n = displacements.Length;
                        int d = displacements[Reduce(Hash(key, 0u, fold), n)];
                        return d < 0 ? -d - 1 : Reduce(Hash(key, (uint)d, fold), n);
                    }
                }
            }
            """;
    }
}
